47	TextSearchQuery::TextSearchQuery(String function_name_, TextSearchMode search_mode_, TextIndexDirectReadMode direct_read_mode_, std::vector<String> tokens_, std::vector<OptimizedRegularExpression> patterns_)
48	    : function_name(std::move(function_name_))
49	    , search_mode(search_mode_)
50	    , direct_read_mode(direct_read_mode_)
