163	bool MergeTreeIndexConditionText::requiresReadingAllTokens(const RPNElement & element)
164	{
165	    switch (element.function)
166	    {
167	        case RPNElement::FUNCTION_OR:
168	        case RPNElement::FUNCTION_NOT:
169	        case RPNElement::FUNCTION_HAS_ANY_TOKENS:
170	        {
171	            return true;
172	        }
173	        case RPNElement::FUNCTION_AND:
174	        case RPNElement::FUNCTION_EQUALS:
175	        case RPNElement::FUNCTION_LIKE:
176	        case RPNElement::FUNCTION_HAS_ALL_TOKENS:
177	        case RPNElement::FUNCTION_UNKNOWN:
178	        case RPNElement::ALWAYS_TRUE:
179	        case RPNElement::ALWAYS_FALSE:
180	        {
181	            return false;
182	        }
183	        case RPNElement::FUNCTION_IN:
184	        case RPNElement::FUNCTION_MATCH:
185	        {
186	            return element.text_search_queries.size() != 1;
187	        }
188	    }
189	}
